import React, { useState } from "react";

export default function Instructors() {

  const [selectedInstructor, setSelectedInstructor] = useState(null);

  const [instructors, setInstructors] = useState([

    {

      id: 1,

      name: "Ravi Kumar",

      email: "ravi@gmail.com",

      subject: "Java Full Stack",

      experience: "5 Years",

      status: "Active"

    },

    {

      id: 2,

      name: "Priya Sharma",

      email: "priya@gmail.com",

      subject: "React JS",

      experience: "3 Years",

      status: "Active"

    },

    {

      id: 3,

      name: "Arjun",

      email: "arjun@gmail.com",

      subject: "PostgreSQL",

      experience: "4 Years",

      status: "Inactive"

    }

  ]);



  const changeStatus = (id) => {

    const updated = instructors.map((ins) => {

      if (ins.id === id) {

        return {

          ...ins,

          status:

            ins.status === "Active"

              ? "Inactive"

              : "Active"

        };

      }

      return ins;

    });



    setInstructors(updated);

  };



  return (

    <div

      style={{

        minHeight: "100vh",

        background:

          "linear-gradient(135deg,#0f172a,#1e293b,#334155)",

        padding: "40px"

      }}

    >

      <h1

        style={{

          textAlign: "center",

          color: "white",

          fontSize: "45px"

        }}

      >

        👨‍🏫 Manage Instructors

      </h1>



      <p

        style={{

          textAlign: "center",

          color: "#cbd5e1",

          marginBottom: "40px"

        }}

      >

        Manage Instructor Details

      </p>





      <div

        style={{

          background: "white",

          padding: "30px",

          borderRadius: "25px",

          boxShadow:

            "0 15px 35px rgba(0,0,0,0.25)"

        }}

      >

        <table

          style={{

            width: "100%",

            borderCollapse: "collapse"

          }}

        >

          <thead>

            <tr>

              <th style={th}>ID</th>

              <th style={th}>Name</th>

              <th style={th}>Email</th>

              <th style={th}>Subject</th>

              <th style={th}>Experience</th>

              <th style={th}>Status</th>

              <th style={th}>Action</th>

            </tr>

          </thead>



          <tbody>

            {

              instructors.map((ins) => (

                <tr key={ins.id}>

                  <td style={td}>{ins.id}</td>

                  <td style={td}>{ins.name}</td>

                  <td style={td}>{ins.email}</td>

                  <td style={td}>{ins.subject}</td>

                  <td style={td}>{ins.experience}</td>



                  <td style={td}>

                    <button

                      onClick={() =>

                        changeStatus(ins.id)

                      }

                      style={{

                        background:

                          ins.status === "Active"

                            ? "#22c55e"

                            : "#ef4444",

                        color: "white",

                        border: "none",

                        padding: "8px 18px",

                        borderRadius: "20px",

                        cursor: "pointer",

                        fontWeight: "bold"

                      }}

                    >

                      {ins.status}

                    </button>

                  </td>



                  <td style={td}>

                    <button

                      style={viewBtn}

                      onClick={() =>

                        setSelectedInstructor(ins)

                      }

                    >

                      View

                    </button>

                  </td>

                </tr>

              ))

            }

          </tbody>

        </table>

      </div>





      {

        selectedInstructor &&

        <div style={detailBox}>

          <h2

            style={{

              color:"#2563eb"

            }}

          >

            Instructor Details

          </h2>

          <hr />



          <p>

            <b>Name :</b>

            {" "}

            {selectedInstructor.name}

          </p>



          <p>

            <b>Email :</b>

            {" "}

            {selectedInstructor.email}

          </p>



          <p>

            <b>Subject :</b>

            {" "}

            {selectedInstructor.subject}

          </p>



          <p>

            <b>Experience :</b>

            {" "}

            {selectedInstructor.experience}

          </p>



          <p>

            <b>Status :</b>

            {" "}

            {selectedInstructor.status}

          </p>



          <button

            style={closeBtn}

            onClick={() =>

              setSelectedInstructor(null)

            }

          >

            Close

          </button>

        </div>

      }

    </div>

  );

}



const th = {

  background:"#2563eb",

  color:"white",

  padding:"18px"

};



const td = {

  padding:"18px",

  textAlign:"center",

  borderBottom:

  "1px solid #e2e8f0"

};



const viewBtn = {

  background:"#8b5cf6",

  color:"white",

  border:"none",

  padding:"10px 18px",

  borderRadius:"10px",

  cursor:"pointer"

};



const closeBtn = {

  background:"#ef4444",

  color:"white",

  border:"none",

  padding:"12px 20px",

  borderRadius:"10px",

  cursor:"pointer",

  marginTop:"20px"

};



const detailBox = {

  background:"white",

  padding:"30px",

  marginTop:"40px",

  borderRadius:"20px",

  boxShadow:

  "0 10px 25px rgba(0,0,0,0.2)"

};
